 85→serve(async (req) => {
 86→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 87→
 88→  // Only accept POST
 89→  if (req.method !== "POST") {
 90→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 91→      status: 405,
 92→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 93→    });
 94→  }
 95→
 96→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 97→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 98→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 99→
100→  // Helper to log and respond
101→  const logAndRespond = async (
102→    status: number,
103→    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
104→    responseBody: Record<string, unknown>
105→  ) => {
106→    try {
107→      await supabase.from("email_ingest_logs").insert({
108→        sender: logData.sender || null,
109→        recipient: logData.recipient || null,
110→        user_id: logData.user_id || null,
111→        job_id: logData.job_id || null,
112→        status: logData.status,
113→        error_message: logData.error_message || null,
114→        attachments_count: logData.attachments_count || 0,
115→        resumes_created: logData.resumes_created || 0,
116→      });
117→    } catch (e) {
118→      console.error("Failed to log email ingest:", e);
119→      await logSystemError({
120→        function_name: "email-ingest",
121→        error_type: "INGEST_LOG_ERROR",
122→        severity: "warning",
123→        error_message: errorToMessage(e),
124→        error_stack: errorToStack(e),
125→        user_id: logData.user_id || null,
126→        job_id: logData.job_id || null,
127→      });
128→    }
129→    return new Response(JSON.stringify(responseBody), {
130→      status,
131→      headers: { ...corsHeaders, "Content-Type": "application/json" },
132→    });
133→  };
134→
135→  try {
136→    // --- [C1 FIX] Verify webhook signature before processing ---
137→    const rawBody = await req.clone().arrayBuffer();
138→    const isValid = await verifyWebhookSignature(req, rawBody);
139→    if (!isValid) {
140→      return await logAndRespond(
141→        401,
142→        { status: "rejected", error_message: "Invalid or missing webhook signature" },
143→        { error: "Unauthorized" }
144→      );
145→    }
146→
147→    // Check global email ingestion toggle
148→    const { data: config } = await supabase
149→      .from("platform_config")
150→      .select("email_ingestion_enabled, max_file_size_mb, max_resumes_per_job")
151→      .limit(1)
152→      .single();
153→
154→    if (config && !config.email_ingestion_enabled) {
155→      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
156→    }
157→
158→    const maxFileSizeBytes = (config?.max_file_size_mb || 10) * 1024 * 1024;
159→    const maxResumesPerJob = config?.max_resumes_per_job || 50;
160→
161→    // Parse incoming payload — support structured JSON and multipart/form-data
162→    let sender: string | null = null;
163→    let recipient: string | null = null;
164→    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
165→
166→    const contentType = req.headers.get("content-type") || "";
167→
168→    if (contentType.includes("application/json")) {
169→      const body = await req.json();
170→
171→      // Structured JSON format (e.g. FromFull/ToFull/Attachments)
172→      if (body.FromFull || body.ToFull || body.Attachments) {
173→        sender = body.FromFull?.Email || body.From ? extractEmail(body.From) : null;
174→
175→        if (body.ToFull && Array.isArray(body.ToFull) && body.ToFull.length > 0) {
176→          recipient = body.ToFull[0].Email?.toLowerCase() || null;
177→        } else if (body.To) {
178→          recipient = extractEmail(body.To);
179→        }
180→
181→        // Attachments: array of { Name, Content (base64), ContentType, ContentLength }
182→        if (body.Attachments && Array.isArray(body.Attachments)) {
183→          let count = 0;
184→          for (const att of body.Attachments) {
185→            if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
186→            if (!att.Name || !att.Content) continue;
187→            // [M2 FIX] Only accept PDF and DOCX
188→            if (!hasAllowedExtension(att.Name)) continue;
189→            const fileContent = Uint8Array.from(atob(att.Content), (c: string) => c.charCodeAt(0));
190→            // [H2 FIX] Enforce file size limit
191→            if (fileContent.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
192→            attachmentFiles.push({ filename: att.Name, content: fileContent });
193→            count++;
194→          }
195→        }
196→      } else {
197→        // Legacy JSON format (backward compatible)
198→        sender = body.sender || null;
199→        recipient = body.recipient || null;
200→
201→        if (body.attachments && Array.isArray(body.attachments)) {
202→          let count = 0;
203→          for (const att of body.attachments) {
204→            if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
205→            if (!att.filename || !att.content) continue;
206→            // [M2 FIX] Enforce file type filter on legacy format too
207→            if (!hasAllowedExtension(att.filename)) continue;
208→            const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
209→            // [H2 FIX] Enforce file size limit
210→            if (fileContent.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
211→            attachmentFiles.push({ filename: att.filename, content: fileContent });
212→            count++;
213→          }
214→        }
215→      }
216→    } else if (contentType.includes("multipart/form-data")) {
217→      // Multipart form-data format (backward compatible)
218→      const formData = await req.formData();
219→
220→      const envelope = formData.get("envelope") as string | null;
221→      const fromField = formData.get("from") as string | null;
222→      const toField = formData.get("to") as string | null;
223→
224→      // Parse sender
225→      if (envelope) {
226→        try {
227→          const env = JSON.parse(envelope);
228→          if (env.from) sender = extractEmail(env.from);
229→        } catch { /* ignore */ }
230→      }
231→      if (!sender && fromField) sender = extractEmail(fromField);
232→
233→      // Parse recipient
234→      if (envelope) {
235→        try {
236→          const env = JSON.parse(envelope);
237→          if (env.to && Array.isArray(env.to) && env.to.length > 0) recipient = extractEmail(env.to[0]);
238→        } catch { /* ignore */ }
239→      }
240→      if (!recipient && toField) recipient = extractEmail(toField.split(",")[0]);
241→
242→      // [M1 FIX] Extract attachments with capped iteration count
243→      const attachmentCount = parseInt(formData.get("attachments") as string || "0", 10);
244→      const maxIter = Math.min(Math.max(attachmentCount, 10), MAX_ATTACHMENTS_PER_EMAIL);
245→      let filesCollected = 0;
246→      for (let i = 1; i <= maxIter && filesCollected < MAX_ATTACHMENTS_PER_EMAIL; i++) {
247→        const file = formData.get(`attachment${i}`) as File | null;
248→        if (!file) continue;
249→        // [M2 FIX] Enforce file type filter on multipart format
250→        const filename = file.name || `attachment_${i}`;
251→        if (!hasAllowedExtension(filename)) continue;
252→        const buffer = await file.arrayBuffer();
253→        // [H2 FIX] Enforce file size limit
254→        if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
255→        attachmentFiles.push({
256→          filename,
257→          content: new Uint8Array(buffer),
258→        });
259→        filesCollected++;
260→      }
261→
262→      // Fallback: check for "attachment-info" pattern
263→      if (attachmentFiles.length === 0) {
264→        for (const [key, value] of formData.entries()) {
265→          if (filesCollected >= MAX_ATTACHMENTS_PER_EMAIL) break;
266→          if (key.startsWith("attachment") && value instanceof File) {
267→            const filename = value.name || key;
268→            // [M2 FIX] Enforce file type filter
269→            if (!hasAllowedExtension(filename)) continue;
270→            const buffer = await value.arrayBuffer();
271→            // [H2 FIX] Enforce file size limit
272→            if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
273→            attachmentFiles.push({
274→              filename,
275→              content: new Uint8Array(buffer),
276→            });
277→            filesCollected++;
278→          }
279→        }
280→      }
281→    } else {
282→      return await logAndRespond(400, { status: "error", error_message: "Unsupported content type" }, { error: "Unsupported content type" });
283→    }
284→
285→    if (!recipient) {
286→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "No recipient" }, { error: "No recipient" });
287→    }
288→
289→    // [L3 FIX] Validate recipient is a properly formatted email
290→    if (!isValidEmail(recipient)) {
291→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "Invalid recipient format" }, { error: "Invalid recipient" });
292→    }
293→
294→    // Step 1: Try per-job routing — match recipient against jobs.inbox_email
295→    let jobId: string | null = null;
296→    let userId: string | null = null;
297→
298→    const { data: jobMatch } = await supabase
299→      .from("jobs")
300→      .select("id, user_id")
301→      .eq("inbox_email", recipient)
302→      .single();
303→
304→    if (jobMatch) {
305→      jobId = jobMatch.id;
306→      userId = jobMatch.user_id;
307→    }
308→
309→    // Step 2: Fall back to user-level inbox routing
310→    if (!userId) {
311→      // Strip +tag for matching: abc+xyz@domain → abc@domain
312→      const baseRecipient = recipient.replace(/\+[^@]*@/, "@");
313→
314→      // [C2 FIX] Use separate parameterized .eq() queries instead of .or() with string interpolation
315→      let profile: { user_id: string; credits: number; email_enabled: boolean; inbox_email: string } | null = null;
316→
317→      const { data: exactMatch } = await supabase
318→        .from("profiles")
319→        .select("user_id, credits, email_enabled, inbox_email")
320→        .eq("inbox_email", recipient)
321→        .limit(1)
322→        .single();
323→
324→      if (exactMatch) {
325→        profile = exactMatch;
326→      } else if (baseRecipient !== recipient) {
327→        const { data: baseMatch } = await supabase
328→          .from("profiles")
329→          .select("user_id, credits, email_enabled, inbox_email")
330→          .eq("inbox_email", baseRecipient)
331→          .limit(1)
332→          .single();
333→        profile = baseMatch;
334→      }
335→
336→      if (!profile) {
337→        return await logAndRespond(404, { sender, recipient, status: "rejected", error_message: "Unknown inbox email" }, { error: "Unknown inbox email" });
338→      }
339→
340→      userId = profile.user_id;
341→
342→      // Check per-user email toggle
343→      if (!profile.email_enabled) {
344→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
345→      }
346→
347→      // [H3 FIX] Check that user has credits before accepting resumes
348→      if (profile.credits <= 0) {
349→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "Insufficient credits" }, { error: "Insufficient credits" });
350→      }
351→    } else {
352→      // Verify the job owner has email enabled and has credits
353→      const { data: profile } = await supabase
354→        .from("profiles")
355→        .select("email_enabled, credits")
356→        .eq("user_id", userId)
357→        .single();
358→
359→      if (profile && !profile.email_enabled) {
360→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
361→      }
362→
363→      // [H3 FIX] Check credits for job-routed emails too
364→      if (profile && profile.credits <= 0) {
365→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Insufficient credits" }, { error: "Insufficient credits" });
366→      }
367→    }
368→
369→    if (attachmentFiles.length === 0) {
370→      return await logAndRespond(400, { sender, recipient, user_id: userId, job_id: jobId, status: "error", error_message: "No valid attachments (only .pdf and .docx accepted)" }, { error: "No valid attachments" });
371→    }
372→
373→    // Find or create job if not already matched by per-job routing
374→    if (!jobId) {
375→      const { data: activeJob } = await supabase
376→        .from("jobs")
377→        .select("id")
378→        .eq("user_id", userId)
379→        .eq("status", "pending")
380→        .order("created_at", { ascending: false })
381→        .limit(1)
382→        .single();
383→
384→      if (activeJob) {
385→        jobId = activeJob.id;
386→      } else {
387→        // [M4 FIX] Rate-limit auto-created jobs: max 5 auto-created jobs per user per day
388→        const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
389→        const { count: recentAutoJobs } = await supabase
390→          .from("jobs")
391→          .select("id", { count: "exact", head: true })
392→          .eq("user_id", userId)
393→          .eq("job_description", "Auto-created from email ingestion")
394→          .gte("created_at", oneDayAgo);
395→
396→        if ((recentAutoJobs || 0) >= 5) {
397→          return await logAndRespond(429, { sender, recipient, user_id: userId, status: "rejected", error_message: "Too many auto-created jobs" }, { error: "Rate limit exceeded" });
398→        }
399→
400→        const { data: newJob } = await supabase
401→          .from("jobs")
402→          .insert({
403→            user_id: userId,
404→            job_description: "Auto-created from email ingestion",
405→            status: "pending",
406→          })
407→          .select("id")
408→          .single();
409→        if (!newJob) throw new Error("Failed to create job");
410→        jobId = newJob.id;
411→      }
412→    }
413→
414→    // [H3 FIX] Check existing resume count for the job before uploading
415→    const { count: existingResumeCount } = await supabase
416→      .from("resumes")
417→      .select("id", { count: "exact", head: true })
418→      .eq("job_id", jobId);
419→
420→    const remainingSlots = maxResumesPerJob - (existingResumeCount || 0);
421→    if (remainingSlots <= 0) {
422→      return await logAndRespond(429, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Job has reached maximum resume limit" }, { error: "Resume limit reached for this job" });
423→    }
424→
425→    // Process attachments (limited to remaining slots)
426→    const resumeIds: string[] = [];
427→    const filesToProcess = attachmentFiles.slice(0, remainingSlots);
428→
429→    for (const att of filesToProcess) {
430→      // [M4 FIX] Sanitize filename to prevent path traversal or injection
431→      const safeName = sanitizeFilename(att.filename);
432→      const filePath = `${userId}/${jobId}/${Date.now()}_${safeName}`;
433→      await supabase.storage.from("resumes").upload(filePath, att.content);
434→
435→      const { data: resume } = await supabase
436→        .from("resumes")
437→        .insert({
438→          job_id: jobId,
439→          filename: safeName,
440→          file_path: filePath,
441→          source: "email",
442→        })
443→        .select("id")
444→        .single();
445→
446→      if (resume) resumeIds.push(resume.id);
447→    }
448→
449→    // Send confirmation email to the user (fire-and-forget)
450→    try {
451→      const { data: authUser } = await supabase.auth.admin.getUserById(userId!);
452→      const userEmail = authUser?.user?.email;
453→
454→      if (userEmail) {
455→        const { data: jobData } = await supabase.from("jobs").select("title, job_description").eq("id", jobId).single();
456→        const jobTitle = jobData?.title || jobData?.job_description?.slice(0, 50) || "Untitled Job";
457→
458→        await supabase.functions.invoke("send-email", {
459→          body: {
460→            to: userEmail,
461→            template_key: "resume_received",
462→            variables: {
463→              user_name: userEmail.split("@")[0],
464→              job_title: jobTitle,
465→              attachment_count: String(filesToProcess.length),
466→              filename: filesToProcess.map((a) => a.filename).join(", "),
467→              job_id: jobId || "",
468→              app_url: Deno.env.get("APP_URL") || "https://rankora.co",
469→            },
470→          },
471→        });
472→      }
473→    } catch (emailErr) {
474→      console.error("Failed to send resume received notification:", emailErr);
475→      await logSystemError({
476→        function_name: "email-ingest",
477→        error_type: "NOTIFICATION_SEND_ERROR",
478→        severity: "warning",
479→        error_message: errorToMessage(emailErr),
480→        error_stack: errorToStack(emailErr),
481→        user_id: userId,
482→        job_id: jobId,
483→      });
484→    }
485→
486→    return await logAndRespond(
487→      200,
488→      { sender, recipient, user_id: userId, job_id: jobId, status: "success", attachments_count: filesToProcess.length, resumes_created: resumeIds.length },
489→      { success: true, resume_ids: resumeIds, job_id: jobId }
490→    );
491→  } catch (err: unknown) {
492→    console.error("email-ingest error:", err);
493→    await logSystemError({
494→      function_name: "email-ingest",
495→      error_type: "INGEST_ERROR",
496→      severity: "critical",
497→      error_message: errorToMessage(err),
498→      error_stack: errorToStack(err),
499→    });
500→    // [H4 FIX] Return generic error — never leak internal details
501→    return new Response(JSON.stringify({ error: "Internal server error" }), {
502→      status: 500,
503→      headers: { ...corsHeaders, "Content-Type": "application/json" },
504→    });
505→  }
506→});
